def setk(parm, keys, expr='cubic()'):
    parm.deleteAllKeyframes()
    # keys: list of (frame, value, slope_per_sec or None)
    fps=hou.fps()
    fr=[k[0] for k in keys]; vals=[k[1] for k in keys]
    for i,(f,v,s) in enumerate(keys):
        if s is None:
            if 0<i<len(keys)-1:
                s=(vals[i+1]-vals[i-1])/((fr[i+1]-fr[i-1])/fps)
            elif i==0 and len(keys)>1: s=(vals[1]-vals[0])/((fr[1]-fr[0])/fps)
            elif len(keys)>1: s=(vals[-1]-vals[-2])/((fr[-1]-fr[-2])/fps)
            else: s=0
        k=hou.Keyframe(); k.setFrame(f); k.setValue(v); k.setSlope(s); k.setInSlope(s)
        k.setExpression(expr,hou.exprLanguage.Hscript); parm.setKeyframe(k)
