import numpy as np
setk=hou.session._setk; g=hou.node('/obj/girl')
def run(ip,iy,end):
    setk(g.parm('look_w'),[(1,0,0),(end,1,0)]); g.parm('idle_pitch').set(ip); g.parm('idle_yaw').set(iy)
    D=hou.session._collect(); bf=D['bf']; hd=D['head']; hf=D['headfwd']
    bd=(bf-hd)/np.linalg.norm(bf-hd,axis=1)[:,None]
    def xc(a,b,rng,maxL=10):
        a=a[rng]; b=b[rng]; out=[]
        for L in range(-maxL,maxL+1):
            if L>=0: x,y=b[:len(b)-L],a[L:]
            else: x,y=b[-L:],a[:len(a)+L]
            out.append((round(np.corrcoef(x,y)[0,1],3),L))
        return max(out)
    yaw=lambda v: np.degrees(np.unwrap(np.arctan2(v[:,0],v[:,2]))); pit=lambda v: np.degrees(np.arcsin(np.clip(v[:,1],-1,1)))
    res=[]
    for rng in (slice(0,264),slice(0,132),slice(0,96)):
        res.append([xc(yaw(hf),yaw(bd),rng)[1],xc(pit(hf),pit(bd),rng)[1],xc(hf[:,0],bd[:,0],rng)[1],xc(hf[:,1],bd[:,1],rng)[1],xc(hf[:,2],bd[:,2],rng)[1], xc(pit(hf),pit(bd),rng)[0]])
    ang=np.degrees(np.arccos(np.clip(np.dot(hf[0],hf[59]),-1,1)))
    return res, round(ang,1), round(pit(hf)[0],1)
for args in [(15,0,10),(12,0,8),(15,0,6),(10,0,6)]:
